id":"S-N","scope_ref":"P1","token":"n","meaning":"抽样检测的样本量","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-D","scope_ref":"P1","token":"d","meaning":"样本中检测出的次品件数","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C","scope_ref":"P1","token":"c","meaning":"拒收临界值，当d≥c时拒收","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C2","scope_ref":"P1","token":"c'","meaning":"接收临界值，当d≤c'时接收","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P0","scope_ref":"P1","token":"p_0","meaning":"标称次品率","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ALPHA","scope_ref":"P1","token":"alpha","meaning":"第一类错误概率（拒收合格批的概率）","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-BETA","scope_ref":"P1","token":"beta","meaning":"第二类错误概率（接收不合格批的概率）","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-YI","scope_ref":"P1","token":"y_i","meaning":"是否检测零配件i（i=1,...,8）","unit":"无量纲","role":"VARIABLE","shape":"INDEXED","domain":"BOOLEAN","index_set":["i"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ZJ","scope_ref":"P1","token":"z_j","meaning":"是否检测半成品j（j=1,2,3）","unit":"无量纲","role":"VARIABLE","shape":"INDEXED","domain":"BOOLEAN","index_set":["j"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-W","scope_ref":"P1","token":"w","meaning":"是否检测成品","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-V","scope_ref":"P1","token":"v","meaning":"是否拆解不合格成品","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-EP","scope_ref":"P1","token":"E[p]","meaning":"次品率的后验期望","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BINOMIAL-MODEL","scope_ref":"P1","statement":"假设每件零配件是否合格是独立的伯努利试验，次品率p为常数，抽样检测结果服从二项分布B(n,p)。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设每件零配件是否合格是独立的伯努利试验，次品率p为常数，抽样检测结果服从二项分布B(n,p)。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEPENDENT-DEFECTS","scope_ref":"P1","statement":"假设零配件1和零配件2的次品事件相互独立，且成品次品率p₃与零配件次品率独立（p₃是给定的装配工艺参数）。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设零配件1和零配件2的次品事件相互独立，且成品次品率p₃与零配件次品率独立（p₃是给定的装配工艺参数）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-LINEAR-COST","scope_ref":"P1","statement":"假设所有成本（购买、检测、装配、拆解、调换）与数量成线性关系，无规模效应。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设所有成本（购买、检测、装配、拆解、调换）与数量成线性关系，无规模效应。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TREE-STRUCTURE","scope_ref":"P1","statement":"假设装配过程严格按图1的树形结构进行，每个半成品只由指定零配件组成，无替代关系。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设装配过程严格按图1的树形结构进行，每个半成品只由指定零配件组成，无替代关系。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BETA-PRIOR","scope_ref":"P1","statement":"假设次品率的先验分布为均匀分布Beta(1,1)，抽样后得到Beta后验分布。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设次品率的先验分布为均匀分布Beta(1,1)，抽样后得到Beta后验分布。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-COST","scope_ref":"P1","statement":"假设抽样检测成本与问题1中设计的样本量相关，且抽样检测在决策前一次性完成。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设抽样检测成本与问题1中设计的样本量相关，且抽样检测在决策前一次性完成。"}},{"kind":"EquationSpec","value":{"equation_id":"E-PART-INSPECT-COMPARE","scope_ref":"P1","expression":"2*N_1 < p_1*N_1*C_post","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N1"],"rhs_symbols":["S-P1","S-N1"],"equation_type":"CONSTRAINT","unit":"元","depends_on":[],"source":"零配件检测决策：比较检测成本与不检测导致的期望损失。"}},{"kind":"EquationSpec","value":{"equation_id":"E-PRODUCT-INSPECT-COMPARE","scope_ref":"P1","expression":"3 < p_3*6","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-P3"],"equation_type":"CONSTRAINT","unit":"元","depends_on":[],"source":"成品检测决策：比较检测成本与不检测导致的调换损失。"}},{"kind":"EquationSpec","value":{"equation_id":"E-EXPECTED-COST","scope_ref":"P1","expression":"TC = 4*N_1 + 18*N_2 + 2*N_1*x_1 + 3*N_2*x_2 + 6*N_asm + 3*N_fin*x_3 + 5*N_def*x_4 + 6*N_mkt","representation":"LATEX_PRESENTATION","lhs_symbols":["S-TC"],"rhs_symbols":["S-N1","S-N2","S-X1","S-X2","S-X3","S-X4"],"equation_type":"OBJECTIVE","unit":"元","depends_on":[],"source":"期望总成本构成（以情况1为例）"}},{"kind":"EquationSpec","value":{"equation_id":"E-POSTERIOR-MEAN","scope_ref":"P1","expression":"E[p] = (d+1)/(n+2)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-EP"],"rhs_symbols":["S-D","S-N"],"equation_type":"DEFINITION","unit":"无量纲","depends_on":[],"source":"期望次品率：E[p] = (d+1)/(n+2)"}},{"kind":"EquationSpec","value":{"equation_id":"E-POSTERIOR","scope_ref":"P1","expression":"p ~ Beta(d+1, n-d+1)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-D","S-N"],"rhs_symbols":["S-D","S-N"],"equation_type":"DEFINITION","unit":"无量纲","depends_on":[],"source":"次品率p的后验分布：Beta(d+1, n-d+1)（假设先验为均匀分布）"}},{"kind":"EquationSpec","value":{"equation_id":"E-TYPE1","scope_ref":"P1","expression":"P(d >= c | p = p_0) <= alpha","representation":"LATEX_PRESENTATION","lhs_symbols":["S-D","S-C"],"rhs_symbols":["S-P0","S-ALPHA"],"equation_type":"CONSTRAINT","unit":"无量纲","depends_on":[],"source":"情形(1)：若d ≥ c（临界值），则拒收。选择最小的n使得当p=0.10时，P(d ≥ c) ≤ 5%"}},{"kind":"EquationSpec","value":{"equation_id":"E-TYPE2","scope_ref":"P1","expression":"P(d <= c' | p = p_0) >= 1 - beta","representation":"LATEX_PRESENTATION","lhs_symbols":["S-D","S-C2"],"rhs_symbols":["S-P0","S-BETA"],"equation_type":"CONSTRAINT","unit":"无量纲","depends_on":[],"source":"情形(2)：若d ≤ c'，则接收。选择最小的n使得当p=0.10时，P(d ≤ c') ≥ 90%"}},{"kind":"ModelSpec","value":{"model_id":"M-DECISION","problem_refs":["P1"],"assumption_refs":["A-BINOMIAL-MODEL","A-INDEPENDENT-DEFECTS","A-LINEAR-COST","A-TREE-STRUCTURE","A-BETA-PRIOR","A-SAMPLING-COST"],"variable_refs":["S-P1","S-P2","S-P3","S-N1","S-N2","S-X1","S-X2","S-X3","S-X4","S-TC","S-N","S-D","S-C","S-C2","S-P0","S-ALPHA","S-BETA","S-YI","S-ZJ","S-W","S-V","S-EP"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1}],"equation_refs":["E-PART-INSPECT-COMPARE","E-PRODUCT-INSPECT-COMPARE","E-EXPECTED-COST","E-POSTERIOR-MEAN","E-POSTERIOR","E-TYPE1","E-TYPE2"],"constraints":["两类错误概率约束","成本与数量线性关系约束","装配树形结构约束"],"objective":"期望总成本最小化","dependencies":[]}}],"code":"const fs=require('fs');function binomCdf(k,n,p){let c=1,s=0;for(let i=0;i<=k&&i<=n;i++){if(i>0)c=c*(n-i+1)/i;s+=c*Math.pow(p,i)*Math.pow(1-p,n-i);}return s;}
const out={};const p0=0.1,alpha=0.05,beta=0.10;
let res1={n:null,c:null};for(let n=1;n<=2000;n++){for(let c=0;c<=n;c++){if(binomCdf(c-1,n,p0)<=alpha){res1={n,c};break;}}}out.case1_min_n=res1.n;out.case1_critical_c=res1.c;
let res2={n:null,cp:null};for(let n=1;n<=2000;n++){for(let cp=n;cp>=0;cp--){if(binomCdf(cp,n,p0)>=1-beta){res2={n,cp};break;}}}out.case2_min_n=res2.n;out.case2_critical_cp=res2.cp;
out.num_strategies_q2=8;out.num_strategies_q3=4096;out.p0=p0;out.alpha=alpha;out.beta=beta;
out.posterior_mean_example=(0+1)/(out.case1_min_n+2);
fs.writeFileSync('decision_outputs.json',JSON.stringify(out,null,2));","run":{"outputBasenames":["decision_outputs.json"],"seed":7},"interpretations":{"results":[{"result_id":"RES-CASE1-N","name":"情形(1)最小样本量n","source":{"locator":"decision_outputs.json","jsonPath":"$.case1_min_n"},"unit":"件"},{"result_id":"RES-CASE1-C","name":"情形(1)拒收临界值c","source":{"locator":"decision_outputs.json","jsonPath":"$.case1_critical_c"},"unit":"件"},{"result_id":"RES-CASE2-N","name":"情形(2)最小样本量n","source":{"locator":"decision_outputs.json","jsonPath":"$.case2_min_n"},"unit":"件"},{"result_id":"RES-CASE2-CP","name":"情形(2)接收临界值c'","source":{"locator":"decision_outputs.json","jsonPath":"$.case2_critical_cp"},"unit":"件"},{"result_id":"RES-STRAT-Q2","name":"问题2策略组合数","source":{"locator":"decision_outputs.json","jsonPath":"$.num_strategies_q2"},"unit":"种"},{"result_id":"RES-STRAT-Q3","name":"问题3策略组合数","source":{"locator":"decision_outputs.json","jsonPath":"$.num_strategies_q3"},"unit":"种"},{"result_id":"RES-POST-MEAN","name":"示例后验期望次品率","source":{"locator":"decision_outputs.json","jsonPath":"$.posterior_mean_example"},"unit":"无量纲"}],"figures":[{"figure_id":"FIG-SAMPLING-PLAN","chart_type":"table","data_refs":["RES-CASE1-N","RES-CASE1-C","RES-CASE2-N","RES-CASE2-CP"],"caption":"问题1抽样检测方案：两种情形下的最小样本量与临界值"}]},"narrative":{"title":"生产过程中的决策问题：建模分析","conclusion":{"claims":[{"text":"在95%信度拒收约束下，情形(1)所需的最小样本量为n，对应拒收临界值c。","quantity_refs":["RES-CASE1-N","RES-CASE1-C"],"representation":{"kind":"rounded","dp":0}},{"text":"在90%信度接收约束下，情形(2)所需的最小样本量为n，对应接收临界值c'。","quantity_refs":["RES-CASE2-N","RES-CASE2-CP"],"representation":{"kind":"rounded","dp":0}},{"text":"问题2的决策空间共8种策略组合，问题3的决策空间共4096种策略组合。","quantity_refs":["RES-STRAT-Q2","RES-STRAT-Q3"],"representation":{"kind":"rounded","dp":0}}]}}}
